={{ (() => {
  const tx = (s, b) => ({ type: 'text', text: s, ...(b ? { marks: [{ type: 'strong' }] } : {}) });
  const inl = s => String(s).split(/(\*\*[^*]+\*\*)/).filter(x => x !== '').map(x => /^\*\*[^*]+\*\*$/.test(x) ? tx(x.slice(2, -2), true) : tx(x));
  const para = s => ({ type: 'paragraph', content: inl(s) });
  const cells = l => l.replace(/^\||\|$/g, '').split('|').map(c => c.trim());
  const item = s => { const m = s.match(/^(CA\d+) — (.*)$/); return { type: 'listItem', content: [{ type: 'paragraph', content: m ? [tx(m[1], true), ...inl(' — ' + m[2])] : inl(s) }] }; };
  const toAdf = md => {
    const lines = String(md ?? '').split('\n');
    const out = [];
    let i = 0;
    while (i < lines.length) {
      const l = lines[i].trim();
      if (!l) { i++; continue; }
      if (l.startsWith('|')) {
        const rows = [];
        while (i < lines.length && lines[i].trim().startsWith('|')) { rows.push(lines[i].trim()); i++; }
        const body = rows.filter(r => !/^\|[\s:|-]+\|?$/.test(r));
        out.push({ type: 'table', attrs: { isNumberColumnEnabled: false, layout: 'default' }, content: body.map((r, k) => ({ type: 'tableRow', content: cells(r).map(c => ({ type: k === 0 ? 'tableHeader' : 'tableCell', attrs: {}, content: [c ? para(c) : { type: 'paragraph', content: [] }] })) })) });
        continue;
      }
      const h = l.match(/^(#{1,6})\s+(.*)$/);
      if (h) { out.push({ type: 'heading', attrs: { level: Math.min(h[1].length + 1, 4) }, content: inl(h[2]) }); i++; continue; }
      if (/^[-*•]\s+/.test(l)) {
        const items = [];
        while (i < lines.length && /^[-*•]\s+/.test(lines[i].trim())) { items.push(item(lines[i].trim().replace(/^[-*•]\s+/, ''))); i++; }
        out.push({ type: 'bulletList', content: items });
        continue;
      }
      out.push(para(l));
      i++;
    }
    return out;
  };
  const prio = p => (p ? { priority: { name: String(p).trim() } } : {});
  return { fields: { project: { key: $('Get project infos').item.json.jira_key }, issuetype: { name: 'Epic' }, summary: $json.epic_title, description: { type: 'doc', version: 1, content: toAdf($json.description) }, ...prio($json.epic_priority) }  };
})() }}

